from packaging.version import Version, InvalidVersion

def latest_stable(versions):
    stable = []
    for v in versions:
        try:
            parsed = Version(v)
        except InvalidVersion:
            continue
        if not parsed.is_prerelease and not parsed.is_postrelease and not parsed.is_devrelease:
            stable.append(parsed)
    if not stable:
        return None
    return str(max(stable))

