final_state.src/duration.py:
def parse_duration(text):
    import re
    match = re.fullmatch(r'(\d+)(ms|s|m)', text.strip())
    if not match:
        raise ValueError(f"Invalid duration: {text}")
    value = int(match.group(1))
    unit = match.group(2)
    if unit == 'ms':
        return value
    elif unit == 's':
        return value * 1000
    elif unit == 'm':
        return value * 60000

