    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    if not text:
        raise ValueError("Empty string")
    # Check for leading sign
    if text[0] == '-':
        raise ValueError("Negative duration not allowed")
    # Split into numeric part and unit
    if text[-2:] == 'ms':
        number_part = text[:-2]
        unit = 'ms'
    elif text[-1] in ('s', 'm'):
        number_part = text[:-1]
        unit = text[-1]
    else:
        raise ValueError("Invalid unit, must end with ms, s, or m")
    if not number_part.isdigit():
        raise ValueError("Non-integer value")
    number = int(number_part)
    if unit == 'ms':
        return number
    elif unit == 's':
        return number * 1000
    elif unit == 'm':
        return number * 60000
    else:
        raise ValueError("Unknown unit")

