def dependency_order(graph):
    # Collect all nodes (including those only in dependency lists)
    all_nodes = set(graph.keys())
    for deps in graph.values():
        all_nodes.update(deps)

    # Build in-degree map and adjacency list for topological sort
    in_degree = {node: 0 for node in all_nodes}
    adj = {node: [] for node in all_nodes}
    for node, deps in graph.items():
        for dep in deps:
            adj[dep].append(node)  # edge from dep to node (dep before node)
            in_degree[node] += 1

    # Use sorted list of nodes with in-degree 0 for deterministic order
    queue = sorted([node for node in all_nodes if in_degree[node] == 0])
    result = []
    while queue:
        node = queue.pop(0)
        result.append(node)
        for neighbor in sorted(adj[node]):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != len(all_nodes):
        raise ValueError("Graph contains a cycle")
    return result

