    # Build reverse adjacency: for each node, list of nodes that depend on it
    rev = {}
    for node, deps in graph.items():
        if node not in rev:
            rev[node] = []
        for dep in deps:
            if dep not in rev:
                rev[dep] = []
            rev[dep].append(node)
    # Also ensure all dependency-only nodes exist
    for deps in graph.values():
        for dep in deps:
            if dep not in rev:
                rev[dep] = []
    # Compute in-degree: number of dependencies for each node
    in_degree = {}
    for node in rev:
        in_degree[node] = 0
    for node, deps in graph.items():
        # in_degree is the count of dependencies for node
        # we set it separately
        pass
    for node in rev:
        in_degree[node] = len(graph.get(node, []))
    # Queue of nodes with no dependencies
    queue = sorted([n for n in rev if in_degree[n] == 0])
    result = []
    while queue:
        node = queue.pop(0)
        result.append(node)
        for dependent in rev.get(node, []):
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                queue.append(dependent)
                queue.sort()
    if len(result) != len(rev):
