import unittest
from src.order import dependency_order

class TestOrder(unittest.TestCase):
    def test_dependencies(self):
        graph = {'app':['db','cache'], 'db':['net'], 'cache':[]}
        result = dependency_order(graph)
        self.assertEqual(set(result), {'app','db','cache','net'})
        self.assertLess(result.index('net'), result.index('db'))
        self.assertLess(result.index('db'), result.index('app'))
        self.assertLess(result.index('cache'), result.index('app'))
    def test_deterministic(self):
        self.assertEqual(dependency_order({'b':[], 'a':[]}), ['a','b'])
    def test_cycle(self):
        with self.assertRaises(ValueError):
            dependency_order({'a':['b'], 'b':['a']})

