def parse_bool(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        stripped = value.strip().lower()
        if stripped in ('true', 'yes', '1'):
            return True
        if stripped in ('false', 'no', '0'):
            return False
    raise ValueError(f"Cannot parse boolean from {value!r}")

