from src.redact import redact

class TestRedact(unittest.TestCase):
    def test_fields(self):
        self.assertEqual(redact('user=a token=secret; api_key=XYZ ok'), 'user=a token=[REDACTED]; api_key=[REDACTED] ok')
    def test_case(self):
