import re

def redact(text):
    # Replace token= or api_key= followed by non-whitespace and non-semicolon characters
    # Case-insensitive, stopping at whitespace or semicolon
    pattern = r'\b(token|api_key)=([^\s;]+)'
    return re.sub(pattern, r'\1=[REDACTED]', text, flags=re.IGNORECASE)

