from collections import deque

def dependency_order(graph):
    # Compute in-degrees
    in_degree = {node: 0 for node in graph}
    for node, deps in graph.items():
        for dep in deps:
            if dep not in in_degree:
                in_degree[dep] = 0
            in_degree[node] += 1

    # Initialize queue with nodes with in-degree 0, in sorted order for determinism
    queue = deque(sorted([node for node in in_degree if in_degree[node] == 0]))
    result = []

    while queue:
        node = queue.popleft()
        result.append(node)
        # Process dependents: any node that depends on current node
        for dependent, deps in graph.items():
            if node in deps:
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    queue.append(dependent)
        # To keep determinism, sort the queue after each addition
        queue = deque(sorted(queue))

    if len(result) != len(in_degree):
        raise ValueError("Graph contains a cycle")

    return result

