def dependency_order(graph):
    # Compute in-degrees and collect all nodes (including those with no outgoing edges)
    in_degree = {}
    for node in graph:
        if node not in in_degree:
            in_degree[node] = 0
        for dep in graph[node]:
            if dep not in in_degree:
                in_degree[dep] = 0
            in_degree[dep] = in_degree.get(dep, 0) + 1

    # Initialize queue with nodes that have in-degree 0, in sorted order for determinism
    queue = deque(sorted([node for node, deg in in_degree.items() if deg == 0]))
    order = []

    while queue:
        node = queue.popleft()
        order.append(node)
        # Decrease in-degree of neighbors
        for neighbor in graph.get(node, []):
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                # Insert in sorted order to maintain determinism
                # Since we use a deque, we'll just add and sort later, but better: use list and sort
                queue.append(neighbor)
                # To keep queue sorted, we can re-sort, but using a simple list and popping from left is fine
                # Actually, we need deterministic order: when multiple nodes have 0 in-degree, pick smallest
        # To maintain sorted order, we should re-sort the queue after adding new nodes
        # Convert deque to sorted list and back to deque
        queue = deque(sorted(queue))

    # If we processed all nodes, return order; otherwise, there's a cycle
    if len(order) != len(in_degree):
        raise ValueError("Cycle detected in dependency graph")

    return order

