from collections import deque

def dependency_order(graph):
    # Include all nodes: keys and values
    all_nodes = set(graph.keys())
    for deps in graph.values():
        all_nodes.update(deps)

    # Build adjacency list and in-degree count
    in_degree = {node: 0 for node in all_nodes}
    # For each edge from dependency to dependent
    for node, deps in graph.items():
        for dep in deps:
            if dep not in graph:
                graph[dep] = []
            # Ensure the dependent is recorded
            if dep not in in_degree:
                in_degree[dep] = 0
            in_degree[node] += 1
        # Ensure key is in in_degree
        if node not in in_degree:
            in_degree[node] = 0

    # Initialize queue with nodes that have no dependencies (in-degree 0)
    queue = deque(sorted([node for node in all_nodes if in_degree[node] == 0]))
    order = []

    while queue:
        node = queue.popleft()
        order.append(node)
        # Decrease in-degree of dependents
        for dependent in graph:
            if node in graph[dependent]:
                in_degree[dependent] -= 1
                if in_degree[dependent] == 0:
                    # Insert sorted to maintain deterministic order
                    # Using list insertion to maintain sorted order efficiently for small graphs
                    # Could also use bisect.insort
                    queue.append(dependent)
                    # Re-sort queue to ensure lexicographic order when multiple become ready
                    queue = deque(sorted(queue))

    if len(order) != len(all_nodes):
        raise ValueError("Cycle detected")

    return order

